package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Region resolution for owner identity. {@link #forPostcode} maps an owner to a region code (the
 * {@code REGION} prefix of the {@code <REGION><FY><HASH8><CHK>} memberId), preferring the postcode: a
 * 4-digit postcode in a known range maps to its region (NSW 2000-2099, VIC 3000-3099, QLD
 * 4000-4099); otherwise it falls back to the city-to-region table (Sydney/NSW, Melbourne/VIC,
 * Brisbane/QLD), and anything unresolved is {@code "UNKNOWN"}. The derived {@code locality} now
 * reads that same region back off the memberId (see {@link #region}).
 */
public final class OwnerLocality {

    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private OwnerLocality() {
    }

    /** Region for the owner's identity, derived from the postcode with the city as fallback. */
    public static String forPostcode(String postcode, String city) {
        String byPostcode = byPostcode(postcode);
        if (byPostcode != null) {
            return byPostcode;
        }
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /** Locality: the region prefix carried in the {@code <REGION><FY><HASH8><CHK>} memberId (the
     *  leading run of letters before the two-digit fiscal year). */
    public static String region(Owner owner) {
        String memberId = owner.getCustomerCode();
        int i = 0;
        while (memberId != null && i < memberId.length() && !Character.isDigit(memberId.charAt(i))) {
            i++;
        }
        return i == 0 ? "UNKNOWN" : memberId.substring(0, i);
    }

    private static String byPostcode(String postcode) {
        if (postcode == null) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        if (value >= 2000 && value <= 2099) {
            return "NSW";
        }
        if (value >= 3000 && value <= 3099) {
            return "VIC";
        }
        if (value >= 4000 && value <= 4099) {
            return "QLD";
        }
        return null;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code memberId} as {@code <REGION><FY><HASH8><CHK>}: the region code derived
 * from the postcode (see {@link OwnerLocality#forPostcode}), the two-digit fiscal year of the
 * registration date (see {@link FiscalYear#twoDigit}), the first eight upper-case hex characters of
 * SHA-256 over the normalized telephone (set by {@link BuildOwner}) concatenated with the last name,
 * and a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (see
 * {@link CustomerCodeCheckDigit}). The id is a pure function of the owner's identity, so it carries no
 * sequence number.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        String region = OwnerLocality.forPostcode(owner.getPostcode(), owner.getCity());
        String fy = FiscalYear.twoDigit(owner.getRegistrationDate());
        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
        String base = region + fy + hash8;
        owner.setCustomerCode(base + CustomerCodeCheckDigit.of(base));
    }

    /** First eight upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns every owner a deterministic {@code householdId}: the first 12 hex characters of SHA-256
 * over {@code normalizedLastName + '|' + postcode}. Owners with the same last name and postcode are
 * therefore the same household and share this id automatically, with no opt-in or back-fill. Runs
 * before the household duplicate block so that block can compare on the computed id.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        String key = normalize(owner.getLastName()) + "|" + orEmpty(owner.getPostcode());
        owner.setHouseholdId(hash12(key));
    }

    /** First 12 lower-case hex characters of SHA-256 over the UTF-8 bytes of {@code key}. */
    private static String hash12(String key) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for an owner's {@code identityKey}, the derived value all duplicate
 * detection is expressed through: the SHA-256 hex of {@code normalizedTelephone + '|' + lowerEmail +
 * '|' + soundex(lastName)}. Two owners are duplicates only when their whole identityKey is equal, so
 * members of the same household (same {@link Soundex} last name and postcode) with different
 * telephones have distinct keys and are a soft match, not a hard duplicate.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    public static String key(Owner owner) {
        return sha256Hex(orEmpty(owner.getTelephone()) + "|" + orEmpty(owner.getEmail()) + "|"
                + Soundex.encode(owner.getLastName()));
    }

    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits an immutable, structured {@code OWNER_CREATED} event on the {@code AUDIT} logger, alongside the
 * human-readable line from {@link AuditOwnerCreated}. Each event carries a monotonically increasing
 * {@code seq} across creates, the owner id, its membership level and the owner's current primary
 * identifier, the memberId (resolved by {@link #primaryIdentifier(Owner)}). Runs after Save so the id
 * is present.
 */
public class EmitOwnerCreatedEvent {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private static final AtomicLong SEQ = new AtomicLong();

    public void service(@Val Owner owner) {
        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
                SEQ.incrementAndGet(), owner.getId(), primaryIdentifier(owner), OwnerMembershipLevel.of(owner));
    }

    /** The owner's primary identifier — the memberId. */
    private static String primaryIdentifier(Owner owner) {
        return owner.getCustomerCode();
    }
}

